using System.Security.Claims;
using System.Text.Json;
using InventorySystem.Controllers;
using InventorySystem.Core.Models;
using InventorySystem.Core.Options;
using InventorySystem.Core.Services;
using InventorySystem.Data;
using InventorySystem.Models;
using InventorySystem.Services.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;
using Microsoft.Extensions.Options;
namespace InventorySystem.Tests;
public class ClientFullWorkflowTests
{
    private static ApplicationDbContext Db()=>new(new DbContextOptionsBuilder<ApplicationDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).ConfigureWarnings(w=>w.Ignore(InMemoryEventId.TransactionIgnoredWarning)).Options);
    private static JsonElement Data(IActionResult r)=>JsonSerializer.SerializeToElement(r is JsonResult j?j.Value:((ObjectResult)r).Value);
    private static async Task Seed(ApplicationDbContext db){db.ItemCategory.AddRange(new ItemCategory{CategoryId=1,CategoryName="Paper",GroupType="RawMaterial",IsActive=true},new ItemCategory{CategoryId=2,CategoryName="Boxes",GroupType="FinishedGoods",IsActive=true},new ItemCategory{CategoryId=3,CategoryName="Another supplier",GroupType="RawMaterial",IsActive=true});db.Items.AddRange(new Items{ItemID=1,CategoryID=1,ItemName="Paper",IsActive=true,ItemType="RawMaterial",StockUnit="kg"},new Items{ItemID=2,CategoryID=2,ItemName="Box",IsActive=true,ItemType="FinishedGoods",StockUnit="pcs"},new Items{ItemID=3,CategoryID=3,ItemName="Other paper",IsActive=true,ItemType="RawMaterial",StockUnit="kg"});await db.SaveChangesAsync();}
    [Theory][InlineData("RawMaterial",1)][InlineData("FinishedGoods",2)]
    public async Task GroupSectionsScopeListsReadsCreatesAndEdits(string type,int expected){using var db=Db();await Seed(db);var c=new CategoryController(db);var rows=Data(await c.GetList(type)).GetProperty("data");Assert.All(rows.EnumerateArray(),g=>Assert.Equal(type,g.GetProperty("GroupType").GetString()));Assert.IsType<NotFoundResult>(await c.GetById(expected,type=="RawMaterial"?"FinishedGoods":"RawMaterial"));var model=new ItemCategoryViewModel{CategoryName="Scoped",GroupType=type,PageGroupType=type,IsActive=true};Assert.True(Data(await c.Save(model)).GetProperty("success").GetBoolean());model.CategoryId=(await db.ItemCategory.SingleAsync(g=>g.CategoryName=="Scoped")).CategoryId;model.PageGroupType=type=="RawMaterial"?"FinishedGoods":"RawMaterial";Assert.False(Data(await c.Save(model)).GetProperty("success").GetBoolean());Assert.Equal(type,(await db.ItemCategory.FindAsync(model.CategoryId))!.GroupType);}
    [Fact]
    public async Task FinishedGroupMenuIsIdempotentAndUsesExistingGroupPermission(){using var db=Db();await db.Database.EnsureCreatedAsync();await DefaultMenuSeeder.ApplyAsync(db);await ClientWorkflowMenuSeeder.ApplyAsync(db);var count=await db.MenuItems.CountAsync();await ClientWorkflowMenuSeeder.ApplyAsync(db);Assert.Equal(count,await db.MenuItems.CountAsync());var page=await db.MenuItems.Include(m=>m.Parent).SingleAsync(m=>m.Controller=="Category"&&m.Action=="FinishedGoods");Assert.Equal("Finished Goods",page.Parent!.Name);Assert.Equal("ItemCategory.View",page.RequiredPermission);}
    private static PurchaseController Buy(ApplicationDbContext db)=>new(db,new LedgerPostingService(db,new AccountService(db)),Options.Create(new AccountingOptions{PostToGeneralLedger=false}),new StockService(db));
    [Fact]
    public async Task PurchaseLookupAndTypedIdsAreRestrictedToChosenGroup(){using var db=Db();await Seed(db);var c=Buy(db);var rows=Data(await c.GetItemOptions("group:1")).GetProperty("items");Assert.Equal(1,Assert.Single(rows.EnumerateArray()).GetProperty("itemID").GetInt64());Assert.Empty(Data(await c.GetItemOptions("group:1",3)).GetProperty("items").EnumerateArray());Assert.IsType<BadRequestObjectResult>(await c.GetItemOptions("group:2"));}
    [Fact]
    public async Task PurchaseSaveRejectsForeignGroupBeforeCreatingAccountOrStock(){using var db=Db();await Seed(db);var m=new PurchaseInvoiceViewModel{VendorID="group:1",PaymentMode=0,PurchaseDate=DateTime.Today,BranchID=1,Items=[new(){Itemid=3,Quantity=5,PurPrice=10}]};Assert.IsType<BadRequestObjectResult>(await Buy(db).Save(m));Assert.Empty(db.PurchaseInvoice);Assert.Empty(db.Parties);Assert.Empty(db.Stock);Assert.Empty(db.AccountLedger);}
    [Fact]
    public async Task PurchaseUpdateRejectsForeignGroupUsingCanonicalNumericVendor(){using var db=Db();await Seed(db);var c=Buy(db);var m=new PurchaseInvoiceViewModel{VendorID="group:1",PaymentMode=0,PurchaseDate=DateTime.Today,BranchID=1,Items=[new(){Itemid=1,Quantity=5,PurPrice=10}]};Assert.IsType<OkObjectResult>(await c.Save(m));m.PurchaseId=(await db.PurchaseInvoice.SingleAsync()).PurchaseId;m.Items[0].Itemid=3;Assert.IsType<BadRequestObjectResult>(await c.Update(m));Assert.Equal(1,(await db.PurchaseInvoiceBody.SingleAsync()).Itemid);Assert.Equal(5,(await db.Stock.SingleAsync()).Quantity);}
    [Fact]
    public async Task MissingProductIsExplainedAndCanBeLinkedBeforeProduction(){using var db=Db();await Seed(db);db.Parties.Add(new(){PartyId=1,PartyName="Buyer",PartyType="customer",Status="active"});db.CostSheet.Add(new(){CostSheetId=1,ItemName="Box",Status="Final",BranchID=1,Plies=[new(){ItemId=1,KGs=.5m,Rate=10}]});await db.SaveChangesAsync();var production=new ProductionController(db,new StockService(db));var info=Data(await production.GetCostSheetInfo(1)).GetProperty("data");Assert.False(info.GetProperty("finishedReady").GetBoolean());Assert.Single(info.GetProperty("issues").EnumerateArray());var c=new CostSheetController(db,new PermissionService(db));Assert.IsType<BadRequestObjectResult>(await c.UpdateFinishedItemLink(new(){CostSheetId=1,FinishedItemId=1}));Assert.IsType<OkObjectResult>(await c.UpdateFinishedItemLink(new(){CostSheetId=1,FinishedItemId=2}));Assert.Empty(Data(await production.GetCostSheetInfo(1)).GetProperty("data").GetProperty("issues").EnumerateArray());Assert.IsType<OkObjectResult>(await production.Save(new(){CostSheetId=1,CustomerId="1",OrderQty=10,OrderDate=DateTime.Today,DeliveryDate=DateTime.Today,AgreedUnitPrice=20}));Assert.Equal(2,(await db.ProductionOrder.SingleAsync()).FinishedItemId);Assert.Empty(db.Stock);}
    [Fact]
    public async Task MissingMaterialsAreShownBeforeProductionAndLinkCannotOverwriteAnotherProduct(){using var db=Db();await Seed(db);db.CostSheet.Add(new(){CostSheetId=1,Status="Final",FinishedItemId=2,Plies=[new(){KGs=.5m}]});await db.SaveChangesAsync();var info=Data(await new ProductionController(db,new StockService(db)).GetCostSheetInfo(1)).GetProperty("data");Assert.Contains(info.GetProperty("issues").EnumerateArray(),e=>e.GetString()!.Contains("paper"));Assert.IsType<ConflictObjectResult>(await new CostSheetController(db,new PermissionService(db)).UpdateFinishedItemLink(new(){CostSheetId=1,FinishedItemId=3}));Assert.Equal(2,(await db.CostSheet.SingleAsync()).FinishedItemId);}
    [Fact]
    public async Task MissingLaminationLinksAreExplainedWithoutWritingOnRead(){using var db=Db();await Seed(db);db.CostSheet.Add(new(){CostSheetId=1,Status="Final",FinishedItemId=2,HasLamination=true,ClientCostingJson=JsonSerializer.Serialize(new ClientCostingOptions{GlueLaminationApplications=1}),Plies=[new(){ItemId=1,KGs=.5m}]});await db.SaveChangesAsync();var info=Data(await new ProductionController(db,new StockService(db)).GetCostSheetInfo(1)).GetProperty("data");Assert.Contains(info.GetProperty("issues").EnumerateArray(),e=>e.GetString()!.Contains("glue lamination"));Assert.Empty(db.ProductionOrder);Assert.Empty(db.ProductionMaterial);}
    [Theory][InlineData("kg",12.75,80)][InlineData("pcs",25,4)]
    public async Task InwardQuantityRemainsActualQuantityRatherThanBundleCalculation(string unit,decimal qty,decimal price){using var db=Db();var c=new GatePassController(db){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new(new ClaimsIdentity([new Claim(ClaimTypes.Name,"QA")],"QA"))}}};var m=new GatePass{Direction="Inward",PartyName="QA",Lines=[new(){Description="Actual goods",Unit=unit,TotalQuantity=qty,UnitPrice=price,CalculateFromBundles=false}]};Assert.IsType<OkObjectResult>(await c.Save(m));var line=await db.GatePassLines.SingleAsync();Assert.Equal(qty,line.TotalQuantity);Assert.Equal(price,line.UnitPrice);Assert.Empty(db.Stock);}
}

